/**
 * `userOwnedTable()` is the ONLY way to declare a table that holds a person's data.
 *
 * It gives every such table the same standard columns, so the scoped data layer
 * (`./scoped.ts`) can protect all of them the same way:
 *
 *   id               uuid, generated by the database
 *   user_id          who owns the row; required; points at the auth `user` table;
 *                    rows are deleted automatically when the user is deleted
 *   client_request_id optional text; the idempotency key (see docs/contracts/foundation.md);
 *                    unique per user, so retries never create duplicates
 *   created_at       set once, by the database
 *   updated_at       set by the database on creation and refreshed on every update
 *
 * Do NOT redeclare any of those names in your own columns.
 *
 * This file is imported by drizzle-kit (plain Node, no bundler), so it must use
 * relative imports only and must not import "server-only".
 */
import { sql } from "drizzle-orm";
import {
  type AnyPgColumn,
  type PgColumnBuilderBase,
  type PgTable,
  type PgTableExtraConfigValue,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";
import type { BuildExtraConfigColumns } from "drizzle-orm";
import { user } from "./schema/auth";

/** Runtime marker proving a table was created by `userOwnedTable()`. */
export const USER_OWNED = Symbol.for("flowzone.user-owned-table");

/** Column names reserved by the standard columns. Domain code may not write them directly. */
export const RESERVED_COLUMNS = [
  "id",
  "userId",
  "clientRequestId",
  "createdAt",
  "updatedAt",
] as const;

function standardColumns() {
  return {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    clientRequestId: text("client_request_id"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => sql`now()` as unknown as Date),
  };
}

type StandardColumns = ReturnType<typeof standardColumns>;

export function userOwnedTable<
  TName extends string,
  TColumns extends Record<string, PgColumnBuilderBase>,
>(
  name: TName,
  columns: TColumns,
  extraConfig?: (
    self: BuildExtraConfigColumns<TName, StandardColumns & TColumns, "pg">,
  ) => PgTableExtraConfigValue[],
) {
  for (const reserved of RESERVED_COLUMNS) {
    if (reserved in columns) {
      throw new Error(`userOwnedTable("${name}"): "${reserved}" is a standard column; remove it.`);
    }
  }

  const table = pgTable(name, { ...standardColumns(), ...columns }, (self) => [
    // One idempotency key per user. NULLs are distinct in Postgres, so rows
    // created without a key never conflict with each other.
    uniqueIndex(`${name}_user_client_request_uq`).on(self.userId, self.clientRequestId),
    ...(extraConfig
      ? extraConfig(
          self as unknown as BuildExtraConfigColumns<TName, StandardColumns & TColumns, "pg">,
        )
      : []),
  ]);

  Object.defineProperty(table, USER_OWNED, { value: true, enumerable: false });
  return table as typeof table & { readonly [USER_OWNED]: true };
}

/** Any table created by `userOwnedTable()`. The scoped layer accepts nothing else. */
export type UserOwnedTable = PgTable & {
  readonly [USER_OWNED]: true;
  readonly id: AnyPgColumn;
  readonly userId: AnyPgColumn;
  readonly clientRequestId: AnyPgColumn;
  readonly createdAt: AnyPgColumn;
  readonly updatedAt: AnyPgColumn;
};

export function isUserOwnedTable(table: unknown): table is UserOwnedTable {
  return (
    typeof table === "object" &&
    table !== null &&
    (table as Record<symbol, unknown>)[USER_OWNED] === true
  );
}
